 jobs=[
 ('Owner / Technical Director / authorised maskinmester','ELOHVAC ApS · May 2023–present','8 employees including 3 apprentices · full P&L',[('People and safety','Lead five electricians and three apprentices: daily planning, 1:1s, development discussions, structured training and safety follow-up. Apply LOTO and risk assessment.'),('Budget and operations','Own quotations, project economics, materials, subcontractors and delivery. AI-assisted schedules and quality checks contributed a documented productivity gain of over 40%.')]),
 ('Co-owner and CTO / Technical Lead, AI department','Data Power Consultant ApS · 2024–Nov 2026 · alongside ELOHVAC','4–10 people · company ceased in November 2026',[('Leadership and priorities','Led AI and AI-coding work with a combined plan and written priority agreements across two organisations; delivered technical applications with documentation and customer handover.')]),
 ('Senior Commissioning Engineer / Project Manager, electrical systems','Novo Nordisk A/S · Nov 2022–Jul 2024','37 concurrent CAPEX projects · 25 specialists',[('Resources and cross-functional delivery','Coordinated engineering, procurement and construction, managing progress, budgets and risk on projects of DKK 2–10 million each.'),('Quality and reporting','FAT/SAT and IQ/OQ/PQ under GMP/FDA/EMA; zero critical deviations at handover. Used SAP ERP for finance and assets and reported monthly to management and client.')]),
 ('Project and Workshop Manager','Ventek-Air · Jan 2022–Nov 2022','14 people · 11 concurrent site projects',[('Capacity and support','Led daily planning and coordination, tracked capacity and progress, and used team meetings and bottleneck analysis to address competing demands.')]),
 ('Operations and Maintenance Manager / Workshop Technician','BIOFOS, Lynetten · Aug 2017–Jan 2022','24/7 operations · technical systems and safety',[('Safe operations','Preventive maintenance and fault finding on electrical and mechanical installations; used LOTO, risk assessments and shift safety routines.')]),
 ('Electromechanical Technician / Production Team Lead','ARJ Engineering · Dec 2003–Mar 2010','12 mechanics and technicians · machine workshop',[('People and delivery','Led shift planning and material coordination while diagnosing and repairing industrial electrical and mechanical equipment.')])]
